71df","hostProviderExport":"bindExternalCredentialReference"},{"capabilityId":"sda-governed-http-exchange-port.v1","conformanceRef":"sha256:5e2ea926b5d4d6528664998fb67a43ffc1f9adb9f660dc38c14335f28b99fd76","implementationRef":"sha256:00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177","kind":"event-port","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["event-port-invocation","single-governed-http-exchange","bounded-response-observation","credential-injection-without-disclosure"],"status":"ADMITTED","hostProvider":"ScenarioKernel.NodePlatform.Effects.GovernedHttpExchange","hostImplementationRef":"languages/typescript/runtimes/node/governed-http-exchange-provider.mjs","hostImplementationDigest":"sha256:67a28e738ade419a256b85c9bc139d1aad0f256d196b28250465d763845a2e5f","hostProviderExport":"observeGovernedHttpExchange"}],"catalogType":"sda-platform-capability-catalog.v1","executionAuthority":{"target":"csharp","pinnedPlatformCommit":"716811046f52dd2a67f9ff308a50d755571cbbad","effectContext":{"module":"languages/typescript/runtimes/node/native-mechanic-primitives.mjs","export":"createGovernedEffectContext","digest":"sha256:1cc204869f0ce7b60ad03187d364db4a432b0b632ce4469a7cf37747d6a379d5"},"runtime":{"command":"dotnet","args":["{estateRoot}/providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ConsumerExecution.dll"],"source":"using System.Text.Json;\nusing System.Text.Json.Nodes;\nusing ScenarioKernel.Adapters.Consumer;\nusing ScenarioKernel.Adapters.Graph;\n\nvar request = JsonNode.Parse(Console.ReadLine()!)!.AsObject();\nvar plan = request[\"plan\"]!.AsObject();\nvar root = request[\"input\"];\nvar physical = request[\"physicalCellIds\"]!.AsArray().Select(x => x!.GetValue<string>()).ToHashSet(StringComparer.Ordinal);\nvar collections = new Dictionary<string, int>(StringComparer.Ordinal);\nvar engine = new SemanticTransformationEngine();\nvar cells = plan[\"canonicalGraph\"]![\"cells\"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x[\"cellId\"]!.GetValue<string>(), StringComparer.Ordinal);\nasync ValueTask<GraphProviderOutcome> ExecuteProvider(JsonNode? input, GraphExecutionContext context, CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();\n    if (physical.Contains(context.CellId))\n    {\n        Console.WriteLine(new JsonObject {\n            [\"type\"] = \"invoke-provider\", [\"cellId\"] = context.CellId,\n            [\"cellExecutionId\"] = context.CellExecutionId, [\"rootExecutionId\"] = context.RootExecutionId,\n            [\"input\"] = input?.DeepClone()\n        }.ToJsonString());\n        var reply = JsonNode.Parse((await Console.In.ReadLineAsync(token))!)!.AsObject();\n        if (reply[\"error\"] is JsonValue error) throw new InvalidOperationException(error.GetValue<string>());\n        return new GraphProviderOutcome(reply[\"outcome\"]?.DeepClone());\n    }\n    var expression = context.Configuration?[\"binding\"]?[\"configuration\"]?[\"expression\"] as JsonObject ?? context.Configuration;\n    if (expression?[\"op\"] is not JsonValue operation)\n    {\n        if (cells[context.CellId][\"execution\"]?[\"authorityId\"]?.GetValue<string>() == \"mechanic:identity.v1\") return new GraphProviderOutcome(input?.DeepClone(), \"VALUE\");\n        throw new InvalidOperationException(\"UNDECLARED_EXECUTION_MECHANIC:\" + context.CellId);\n    }\n    try\n    {\n        var entering = context.DecompositionInput ?? input;\n        var outcome = engine.Transform(expression, entering, root);\n        if (outcome is null) throw new InvalidOperationException(\"LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE\");\n        if (new[] { \"map\", \"flat-map\", \"filter\", \"find\", \"some\", \"every\" }.Contains(operation.GetValue<string>(), StringComparer.Ordinal))\n        {\n            var occurrence = collections.GetValueOrDefault(context.CellId);\n            collections[context.CellId] = occurrence + 1;\n            var source = expression[\"from\"] is JsonObject from ? engine.Transform(from, entering, root) as JsonArray : null;\n            return new GraphProviderOutcome(outcome, occurrence < (source?.Count ?? 0) ? \"CONTINUE\" : \"STOP\");\n        }\n        return new GraphProviderOutcome(outcome);\n    }\n    catch (InvalidOperationException)\n    {\n        return new GraphProviderOutcome(input?.DeepClone(), \"VALUE\");\n    }\n}\nasync ValueTask<bool> Admit(JsonNode? value, GraphExecutionContext context, string direction, CancellationToken token)\n{\n    Console.WriteLine(new JsonObject { [\"type\"] = \"admit-contract\", [\"cellId\"] = context.CellId,\n        [\"cellExecutionId\"] = context.CellExecutionId, [\"rootExecutionId\"] = context.RootExecutionId,\n        [\"direction\"] = direction, [\"value\"] = value?.DeepClone() }.ToJsonString());\n    var reply = JsonNode.Parse((await Console.In.ReadLineAsync(token))!)!.AsObject();\n    if (reply[\"error\"] is JsonValue error) throw new InvalidOperationException(error.GetValue<string>());\n    return reply[\"admitted\"]?.GetValue<bool>() == true;\n}\nasync ValueTask<GraphProviderOutcome> Provider(JsonNode? input, GraphExecutionContext context, CancellationToken token)\n{\n    if (!await Admit(input, context, \"input\", token)) return new GraphProviderOutcome(input?.DeepClone(), \"INPUT_REJECTED\", \"rejected\");\n    var outcome = await ExecuteProvider(input, context, token);\n    if (!await Admit(outcome.OutcomeValue, context, \"outcome\", token)) return new GraphProviderOutcome(outcome.OutcomeValue, \"OUTCOME_REJECTED\", \"rejected\");\n    return outcome;\n}\n\nvar authorities = plan[\"bindingAuthorities\"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x[\"id\"]!.GetValue<string>(), StringComparer.Ordinal);\nValueTask<JsonNode?> ProjectBinding(string identity, JsonNode? value, CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();\n    return ValueTask.FromResult(engine.Transform(authorities[identity][\"binding\"]![\"configuration\"]![\"expression\"]!.AsObject(), value, root));\n}\nvar providers = plan[\"realizationOverlay\"]![\"providerBindings\"]!.AsArray()\n    .Select(x => x![\"providerProfileId\"]!.GetValue<string>()).Distinct(StringComparer.Ordinal)\n    .ToDictionary(identity => identity, _ => (GraphProvider)Provider, StringComparer.Ordinal);\nvar result = await new SemanticExecutionGraphScheduler(plan, providers, ProjectBinding).ExecuteAsync(root, request[\"rootExecutionId\"]!.GetValue<string>());\nConsole.WriteLine(new JsonObject { [\"type\"] = \"result\", [\"result\"] = result }.ToJsonString());\n","sourceDigest":"sha256:00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177","dependencies":[{"root":"sdaRoot","path":"languages/csharp/src/ScenarioKernel.Adapters/Graph/SemanticExecutionGraphScheduler.cs","digest":"sha256:e1ae899393c78b6e179d9a5300f94d7617cf043b0e0c6f85ee4b84f24ab3f8ca"},{"root":"sdaRoot","path":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/SemanticTransformationEngine.cs","digest":"sha256:fd67dd950b66ce60933f3027f5f4001e52883622d94549231121aafcbf4c0e93"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ConsumerExecution.deps.json","digest":"sha256:ecf470605df840980934099a537ced554cda569ce2c7cdc84dd5e4432dc6c6a3"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ConsumerExecution.dll","digest":"sha256:fb5f9995d4cd9c307c0f331c0b40719a9b3c084d4b493a9769f0b769f4e466a9"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ConsumerExecution.runtimeconfig.json","digest":"sha256:256dda2706e1151bb95987b6b5be610bf68d64e058285b19e7e958222fc90414"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ScenarioKernel.Adapters.dll","digest":"sha256:5958b088f53e19370ab9e08cf764789f0cd4be45fc158a144a5d33296ade0ef4"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ScenarioKernel.Contracts.dll","digest":"sha256:2ee3332365aab74bd6e15413e08519d2dc81b22397a39f3cdb4b2ececb2b6ddf"},{"root":"estateRoot","path":"providers/consumer-execution/00e1f2b2b4e27a1bb72fcfe3a5e14eca0301e39fc4bbd67d46347347f9cae177/ScenarioKernel.Execution.dll","digest":"sha256:356e3a55eed08760f25eaa74a77e0b764900659d3a62c5bf5cbcd7e8717b62ec"}],"timeoutMilliseconds":60000,"maximumOutputBytes":16777216,"environment":{}},"contractAdmission":{"providerId":"ScenarioKernel.NodePlatform.Schema.JsonSchemaContractAdmission","module":"languages/typescript/runtimes/node/schema-contract-admission-provider.mjs","export":"createSynchronousSchemaAdmission","digest":"sha256:b8b8b60d0023d2ab0bff2d1239a3e19d73ebe2d4405b47cef006004b370eac5a"}}}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
DECLARE @provider bigint=(SELECT provider_pk FROM model.provider WHERE semantic_object_pk=@object),@next bigint=(SELECT provider_definition_pk FROM model.provider_definition WHERE semantic_object_definition_pk=@definition);
IF @next IS NULL BEGIN
 INSERT model.provider_definition(provider_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,name,declaration_profile,object_kind,_owner_definition_pk,_canonical_pointer)
 VALUES(@provider,@object,@definition,@digest,N'ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform','sda-platform-capability-catalog.v1','PROVIDER',@definition,N''); SET @next=SCOPE_IDENTITY();
END;
INSERT model.provider_capability_implementation(provider_definition_pk,capability_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @next,capability_version_pk,role,@definition,_canonical_pointer FROM model.provider_capability_implementation i WHERE provider_definition_pk=@previous AND NOT EXISTS(SELECT 1 FROM model.provider_capability_implementation n WHERE n.provider_definition_pk=@next AND n.capability_version_pk=i.capability_version_pk);
INSERT model.provider_mechanic_implementation(provider_definition_pk,mechanic_version_pk,provider_profile_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @next,mechanic_version_pk,provider_profile_version_pk,role,@definition,_canonical_pointer FROM model.provider_mechanic_implementation i WHERE provider_definition_pk=@previous AND NOT EXISTS(SELECT 1 FROM model.provider_mechanic_implementation n WHERE n.provider_definition_pk=@next AND n.mechanic_version_pk=i.mechanic_version_pk AND (n.provider_profile_version_pk=i.provider_profile_version_pk OR n.provider_profile_version_pk IS NULL AND i.provider_profile_version_pk IS NULL));
INSERT model.provider_port_implementation(provider_definition_pk,port_version_pk,provider_profile_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @next,port_version_pk,provider_profile_version_pk,role,@definition,_canonical_pointer FROM model.provider_port_implementation i WHERE provider_definition_pk=@previous AND NOT EXISTS(SELECT 1 FROM model.provider_port_implementation n WHERE n.provider_definition_pk=@next AND n.port_version_pk=i.port_version_pk AND n.provider_profile_version_pk=i.provider_profile_version_pk);
IF @next<>@previous BEGIN
 DELETE i FROM model.binding_port_implementation i JOIN model.provider_binding b ON b.provider_binding_pk=i.provider_binding_pk WHERE b.provider_definition_pk=@previous;
 UPDATE model.provider_binding SET provider_definition_pk=@next WHERE provider_definition_pk=@previous;
 INSERT model.binding_port_implementation(provider_binding_pk,provider_slot_pk,slot_port_requirement_pk,port_version_pk,provider_definition_pk,provider_port_implementation_pk,_owner_definition_pk,_canonical_pointer)
 SELECT b.provider_binding_pk,b.provider_slot_pk,r.slot_port_requirement_pk,r.port_version_pk,@next,i.provider_port_implementation_pk,b._owner_definition_pk,b._canonical_pointer
 FROM model.provider_binding b JOIN model.provider_binding_scope scope ON scope.provider_binding_scope_pk=b.provider_binding_scope_pk
 JOIN model.binding_context context ON context.binding_context_pk=scope.binding_context_pk JOIN model.slot_port_requirement r ON r.provider_slot_pk=b.provider_slot_pk
 JOIN model.provider_port_implementation i ON i.provider_definition_pk=@next AND i.port_version_pk=r.port_version_pk AND i.provider_profile_version_pk=context.provider_profile_version_pk WHERE b.provider_definition_pk=@next;
END;
SELECT N'csharp' AS target,@next AS provider_definition_pk;
GO
